    cache = OrderedDict()  # key -> [value, write_time]
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                write_time = cache[key][1]
                if write_time + ttl <= t:
                    # expired
                    del cache[key]
            if key in cache:
                cache[key][0] = value
                cache[key][1] = t
                cache.move_to_end(key)
